import * as THREE from 'three';
// Original generated coastal concrete: flat scan, salt wear, fine aggregate; 256px JPEG.
const DATA='data:image/jpeg;base64,';
export function shoreConcrete(){const t=new THREE.TextureLoader().load(DATA);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;return t;}

// Original generated nine-panel coastal material atlas, cropped to 256px JPEGs.
const SURFACES = [
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
'data:image/jpeg;base64,',
];
export function surface(i){ const t=new THREE.TextureLoader().load(SURFACES[i]);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;return t;}
const CITY='data:image/jpeg;base64,';
export function cityBackdrop(){const t=new THREE.TextureLoader().load(CITY);t.magFilter=THREE.LinearFilter;return t;}

// Small original canvas atlases for the coast's close surfaces. Shared per material.
const detailCache = new Map();
export function coastalDetail(kind) {
  if(detailCache.has(kind))return detailCache.get(kind);
  const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');
  let state=7919;const rand=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};
  g.fillStyle=kind==='wood'?'#b6aa91':kind==='boards'?'#c9c6b6':kind==='cliff'?'#babbae':'#dedbd1';g.fillRect(0,0,256,256);
  for(let i=0;i<14000;i++){const v=rand();g.fillStyle=`rgba(${v>.5?'255,255,238':'35,37,30'},${.04+rand()*.13})`;g.fillRect(rand()*256,rand()*256,kind==='wood'?12:2,1+rand()*3);}
  if(['wood','boards'].includes(kind))for(let y=0;y<256;y+=32){g.fillStyle='#686b62';g.fillRect(0,y,256,2);g.fillStyle='#ede6d0';g.fillRect(0,y+2,256,1);for(let x=16;x<256;x+=64){g.fillStyle='#696a62';g.fillRect(x,y+6,2,2);}}
  if(kind==='cliff')for(let i=0;i<130;i++){const x=rand()*256,y=rand()*256;g.strokeStyle='rgba(58,65,52,.3)';g.lineWidth=1+rand()*3;g.beginPath();g.moveTo(x,y);g.lineTo(x+rand()*30-15,y+20);g.lineTo(x+20,y+40);g.stroke();}
  if(kind==='leaves'){
    g.clearRect(0,0,256,256);
    for(let i=0;i<180;i++){const a=rand()*Math.PI*2,r=Math.sqrt(rand())*108,x=128+Math.cos(a)*r,y=136+Math.sin(a)*r*.85;g.fillStyle=['#536346','#77835a','#93986b','#66794e'][i%4];g.beginPath();g.ellipse(x,y,5+rand()*9,2+rand()*4,a,0,7);g.fill();}
  }
  if(kind==='scrub'){
    g.fillStyle='#92956b';g.fillRect(0,0,256,256);
    for(let i=0;i<9500;i++){
      const x=rand()*256,y=rand()*256;
      g.fillStyle=['#697448','#87935a','#b1ac7b','#4e6342','#c2b68b'][i%5];
      g.fillRect(x,y,1+rand()*5,1+rand()*3);
    }
    for(let i=0;i<120;i++){
      const x=rand()*256,y=rand()*256;
      g.fillStyle=i%3?'rgba(47,69,40,.22)':'rgba(213,197,149,.3)';
      g.beginPath();g.ellipse(x,y,3+rand()*16,2+rand()*6,rand()*3,0,7);g.fill();
    }
  }
  if(kind==='meadow'){
    g.fillStyle='#b0ad8c';g.fillRect(0,0,256,256);
    for(let i=0;i<150;i++){
      const x=rand()*256,y=rand()*256,r=9+rand()*32;
      g.fillStyle=['rgba(67,83,48,.18)','rgba(136,142,94,.3)','rgba(219,202,160,.28)'][i%3];
      for(const dx of [-256,0,256])for(const dy of [-256,0,256]){g.beginPath();g.ellipse(x+dx,y+dy,r,r*.85,rand()*3,0,7);g.fill();}
    }
    for(let i=0;i<15000;i++){
      g.fillStyle=['#788060','#a4a17d','#c2b68d','#d0c49f','#8d9271'][i%5];
      g.fillRect(rand()*256,rand()*256,.5+rand()*1.4,.5+rand()*2);
    }
  }
  if(kind==='window'){
    g.fillStyle='#283b39';g.fillRect(0,0,256,256);g.fillStyle='#8a7759';g.fillRect(10,135,235,9);g.fillRect(10,205,235,8);
    for(let i=0;i<15;i++){g.fillStyle=['#b6ab88','#757c68','#9e7953'][i%3];g.fillRect(15+i*15,153+rand()*20,9,29);}
    const light=g.createLinearGradient(0,0,256,230);light.addColorStop(0,'rgba(180,211,216,.55)');light.addColorStop(.45,'rgba(180,211,216,.07)');light.addColorStop(1,'rgba(180,211,216,.2)');g.fillStyle=light;g.fillRect(0,0,256,256);
    g.fillStyle='#dad6bf';g.fillRect(0,0,256,9);g.fillRect(0,247,256,9);g.fillRect(0,0,9,256);g.fillRect(247,0,9,256);g.fillRect(124,0,8,256);
  }
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;detailCache.set(kind,t);return t;
}
